// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2004,"grade":"3-7","contest":"Золотое руно","letters":"АБВГД","count":30,"language":"ru","points":3,"tasksFile":"tasks-3-7.pdf","answersFile":"reviewed-3-7.pdf","sections":[{"start":1,"title":"Олимпийские символы"},{"start":6,"title":"Искусство разных эпох"},{"start":11,"title":"Герои мифов"},{"start":16,"title":"Игры в литературе"},{"start":21,"title":"Спортивные игры"},{"start":26,"title":"Музыкальные инструменты"}],"matchingGroups":[{"start":1,"count":5,"title":"Олимпийские города","question":"Где проходили Олимпийские игры? Подбери город и год к каждому из пяти плакатов."}],"reviewedKey":true}, [{"question":"На каких Олимпийских играх использовали этот символ?","choices":["Рим 1960","Берлин 1936","Париж 1924","Лондон 1948","Токио 1964"],"answer":0,"title":"Волчица на эмблеме","figure":{"src":"assets/golden-fleece/2004/2004_01_big.jpg","alt":"Красный знак с волчицей и римскими цифрами.","width":200,"height":226},"steps":["На эмблеме написано ROMA, то есть Рим. Волчица над надписью отсылает к легенде о Ромуле и Реме, основателях города.","Римские цифры MCMLX дают 1000 + 900 + 60 = 1960. Надпись и дата указывают на Игры в Риме в 1960 году."],"reviewedEdition":true},{"question":"На каких Олимпийских играх использовали этот символ?","choices":["Рим 1960","Берлин 1936","Париж 1924","Лондон 1948","Токио 1964"],"answer":2,"title":"Флаг на плакате","figure":{"src":"assets/golden-fleece/2004/2004_02_big.jpg","alt":"Атлеты поднимают руки на фоне трёхцветного полотнища.","width":200,"height":229},"steps":["На плакате спортсмены поднимают руки на фоне французского триколора. У ног спортсменов видны пальмовые ветви.","Эти детали отличают работу художника Жана Друа, которую Олимпийский музей относит к Играм в Париже в 1924 году."],"reviewedEdition":true},{"question":"На каких Олимпийских играх использовали этот символ?","choices":["Рим 1960","Берлин 1936","Париж 1924","Лондон 1948","Токио 1964"],"answer":1,"title":"Колесница на плакате","figure":{"src":"assets/golden-fleece/2004/2004_03_big.jpg","alt":"Атлет в венке, олимпийские кольца и тёмный силуэт колесницы с четырьмя конями.","width":200,"height":233},"steps":["Справа под спортсменом виден силуэт колесницы, запряжённой четырьмя лошадьми. Такая квадрига венчает Бранденбургские ворота.","Бранденбургские ворота находятся в Берлине. Художник Франц Вюрбель поместил их на официальный плакат Берлинских игр 1936 года."],"reviewedEdition":true},{"question":"На каких Олимпийских играх использовали этот символ?","choices":["Рим 1960","Берлин 1936","Париж 1924","Лондон 1948","Токио 1964"],"answer":3,"title":"Часовая башня на плакате","figure":{"src":"assets/golden-fleece/2004/2004_04_big.jpg","alt":"Белая фигура метателя диска на фоне дворца с часовой башней.","width":200,"height":226},"steps":["За дискоболом видны Вестминстерский дворец и часовая башня. Большой колокол в этой башне известен под названием Биг-Бен.","Вестминстерский дворец находится в Лондоне. Олимпийский символ относится к лондонским Играм 1948 года."],"reviewedEdition":true},{"question":"На каких Олимпийских играх использовали этот символ?","choices":["Рим 1960","Берлин 1936","Париж 1924","Лондон 1948","Токио 1964"],"answer":4,"title":"Красный диск на эмблеме","figure":{"src":"assets/golden-fleece/2004/2004_05_big.jpg","alt":"Большой красный круг над пятью олимпийскими кольцами.","width":200,"height":229},"steps":["Над пятью олимпийскими кольцами находится красный диск. Такая форма и цвет обозначают солнце на государственном флаге Японии.","Из предложенных городов в Японии находится Токио. Этот знак разработали для летних Игр 1964 года."]},{"question":"В каком веке написали эту картину со спортсменами?","choices":["V век до н. э.","XX век","XIX век","Около 1600 года до н. э.","VI век до н. э."],"answer":1,"title":"Игра в полосатой форме","figure":{"src":"assets/golden-fleece/2004/2004_06_big.jpg","alt":"Четверо спортсменов в полосатой форме играют с мячом среди деревьев.","width":200,"height":254},"steps":["На полотне четыре спортсмена в полосатой форме перебрасывают мяч. Это картина Анри Руссо «Футболисты» из собрания Музея Гуггенхайма.","Руссо написал картину в 1908 году. Этот год относится к XX веку."],"reviewedEdition":true},{"question":"В каком веке создали греческий оригинал этой скульптуры, известный по римским копиям?","choices":["V век до н. э.","XX век","XIX век","Около 1600 года до н. э.","VI век до н. э."],"answer":0,"title":"Атлет с диском","figure":{"src":"assets/golden-fleece/2004/2004_07_big.jpg","alt":"Атлет наклонился и отвёл за спину руку с круглым диском.","width":200,"height":269},"steps":["Атлет отвёл назад руку с диском перед броском. Такая поза позволяет узнать «Дискобола» Мирона.","Бронзовый оригинал Мирона относится к V веку до нашей эры. Сейчас его облик известен по римским копиям."],"reviewedEdition":true},{"question":"Когда, по музейной датировке, была создана эта фреска?","choices":["V век до н. э.","XX век","XIX век","Около 1600 года до н. э.","VI век до н. э."],"answer":3,"title":"Два юных боксёра","figure":{"src":"assets/golden-fleece/2004/2004_08_big.jpg","alt":"Двое мальчиков на красноватой фреске подняли руки в боксёрских перчатках.","width":200,"height":310},"steps":["Двое мальчиков с поясами и перчатками подняли руки. Эту фреску нашли в доисторическом поселении Акротири на острове Тира.","Археологический музей Афин и каталог Министерства культуры Греции датируют «Боксирующих мальчиков» примерно 1600 годом до нашей эры."],"reviewedEdition":true},{"question":"В каком веке написали показанное на репродукции полотно?","choices":["V век до н. э.","XX век","XIX век","Около 1600 года до н. э.","VI век до н. э."],"answer":2,"title":"Люди на волжском берегу","figure":{"src":"assets/golden-fleece/2008/2008_57_II-30.jpg","alt":"Люди идут вдоль реки и тянут лямки, вдали видны суда.","width":472,"height":213},"steps":["Люди на берегу Волги тянут судно на лямках. По этому сюжету узнаётся картина Ильи Репина «Бурлаки на Волге».","Репин закончил картину в 1873 году. Этот год относится к XIX веку."],"adaptation":"Учебная репродукция и вопрос о картине Ильи Репина.","reviewedEdition":true},{"question":"В каком веке был создан этот древнегреческий рельеф с борцами?","choices":["V век до н. э.","XX век","XIX век","Около 1600 года до н. э.","VI век до н. э."],"answer":4,"title":"Борцы на рельефе","figure":{"src":"assets/golden-fleece/2004/2004_10_big.jpg","alt":"На каменном рельефе двое борются, по сторонам ещё два атлета.","width":489,"height":180},"steps":["На рельефе двое атлетов сцепились в борьбе. Такой рельеф украшал базу куроса из афинского Керамика.","Музей датирует памятник примерно 510 годом до нашей эры. Это VI век до нашей эры."],"reviewedEdition":true},{"question":"Кто из героев греческих мифов совершил следующие поступки:\n\nВызвал Аполлона на музыкальное состязание и поплатился за это жизнью.","choices":["Пелопс","Гиацинт","Марсий","Амик","Антей"],"answer":2,"title":"Музыкальный вызов","steps":["Сатир вызвал Аполлона на состязание музыкантов. Аполлон играл на лире, а сатир — на авлосе.","Соперник проиграл и по условиям состязания подвергся наказанию. Это Марсий."]},{"question":"Кто из героев греческих мифов совершил следующие поступки:\n\nСчитался непревзойденным кулачным бойцом, но проиграл состязание одному из аргонавтов, юноше Полидевку.","choices":["Пелопс","Гиацинт","Марсий","Амик","Антей"],"answer":3,"title":"Кулачный поединок","steps":["Жестокий царь бебриков заставлял чужестранцев драться с ним на кулаках. На этот раз его вызов принял Полидевк из команды «Арго».","Полидевк победил царя. Имя проигравшего бойца — Амик."]},{"question":"Кто из героев греческих мифов совершил следующие поступки:\n\nСостязался с Гераклом в искусстве борьбы.","choices":["Пелопс","Гиацинт","Марсий","Амик","Антей"],"answer":4,"title":"Борьба с Гераклом","steps":["В мифе великан возвращал себе силу каждый раз, когда касался земли, своей матери. Поэтому Геракл поднял противника над землёй.","Так он смог одолеть великана Антея. В условии речь именно об этой борьбе."]},{"question":"Кто из героев греческих мифов совершил следующие поступки:\n\nОбманом выиграл конное ристалище у царя Эномая.","choices":["Пелопс","Гиацинт","Марсий","Амик","Антей"],"answer":0,"title":"Колесница Эномая","steps":["Эномай обещал выдать дочь Гипподамию за победителя гонки на колесницах. В одном из рассказов участник подговорил возничего испортить крепления колёс соперника.","Этим победителем оказался Пелопс. От его имени происходит название полуострова Пелопоннес."]},{"question":"Кто из героев греческих мифов совершил следующие поступки:\n\nСлучайно погиб, соревнуясь с Аполлоном в метании диска.","choices":["Пелопс","Гиацинт","Марсий","Амик","Антей"],"answer":1,"title":"Бросок диска","steps":["В мифе юноша состязался с Аполлоном в метании диска. Диск поразил его, и юноша погиб.","Это Гиацинт. Миф связывает с его гибелью появление одноимённого цветка."]},{"question":"Кто автор литературных произведений, из которых взяты следующие отрывки, описывающие игровые эпизоды?\n\n«Давненько не брал я в руки шашек!»","choices":["В. Набоков","Н. Гоголь","А. Пушкин","Г. Гессе","Ф. Достоевский"],"answer":1,"title":"Партия в шашки","steps":["Посмотри, кто предлагает шашки в русской классике. Ноздрёв пытается играть с Чичиковым и двигает шашки вопреки правилам.","Эпизод находится в «Мёртвых душах». Автор поэмы — Николай Гоголь."]},{"question":"Кто автор литературных произведений, из которых взяты следующие отрывки, описывающие игровые эпизоды?\n\n«Однажды человек десять наших офицеров обедали у Сильвио. После обеда стали мы уговаривать хозяина прометать нам банк».","choices":["В. Набоков","Н. Гоголь","А. Пушкин","Г. Гессе","Ф. Достоевский"],"answer":2,"title":"Карты у Сильвио","steps":["«Прометать банк» означает выступить банкометом в карточной игре. Имя Сильвио помогает найти произведение с этим эпизодом.","Сильвио — герой повести «Выстрел» из «Повестей Белкина» Александра Пушкина."]},{"question":"Кто автор литературных произведений, из которых взяты следующие отрывки, описывающие игровые эпизоды?\n\n«Во всех шахматных клубах прослеживали возможные продолжения, отмечали слабый пункт у белых на d3, но никто не мог найти ключ к бесспорной победе».","choices":["В. Набоков","Н. Гоголь","А. Пушкин","Г. Гессе","Ф. Достоевский"],"answer":0,"title":"Шахматный анализ","steps":["Запись d3 обозначает клетку шахматной доски. Произведение показывает, как шахматисты разбирают варианты партии.","Этот эпизод взят из романа «Защита Лужина» Владимира Набокова. Его главный герой — шахматист."]},{"question":"Кто автор литературных произведений, из которых взяты следующие отрывки, описывающие игровые эпизоды?\n\n«Конечно, это был редкий случай, что на каких-нибудь десяти ударах три раза выскочил зеро».","choices":["В. Набоков","Н. Гоголь","А. Пушкин","Г. Гессе","Ф. Достоевский"],"answer":4,"title":"Три выпадения зеро","steps":["Термин «зеро» указывает на рулетку. Именно такая игра определяет судьбу Алексея Ивановича и других героев произведения.","Цитата из романа «Игрок», который написал Фёдор Достоевский."]},{"question":"Кто автор литературных произведений, из которых взяты следующие отрывки, описывающие игровые эпизоды?\n\n«Игра была не просто упражнением и не просто отдыхом, она олицетворяла гордую дисциплину ума».","choices":["В. Набоков","Н. Гоголь","А. Пушкин","Г. Гессе","Ф. Достоевский"],"answer":3,"title":"Игра для ума","steps":["В центре отрывка интеллектуальная игра, которой посвящают годы учёбы. В романе она соединяет музыку, математику и другие области знания.","Герман Гессе описал её в «Игре в бисер». Главный герой Йозеф Кнехт становится мастером игры."]},{"question":"В каких странах были придуманы современные виды следующих спортивных игр:\n\nГандбол.","choices":["Шотландия","Англия","Дания","Канада","США"],"answer":2,"title":"История гандбола","steps":["Игры с мячом руками существовали давно, а вопрос относится к современному спортивному гандболу. Из ранних письменных правил выделяются правила Хольгера Нильсена начала XX века.","Нильсен составил их в Дании. Своя роль в формировании современного гандбола была и у немецких спортивных педагогов."]},{"question":"В каких странах были придуманы современные виды следующих спортивных игр:\n\nХоккей.","choices":["Шотландия","Англия","Дания","Канада","США"],"answer":3,"title":"Хоккей с шайбой","steps":["У современных правил хоккея важная веха — игра в помещении по установленным правилам. В 1875 году такой матч прошёл в Монреале.","Монреаль находится в Канаде, где игра в хоккей с шайбой получила раннее развитие."]},{"question":"В каких странах были придуманы современные виды следующих спортивных игр:\n\nБадминтон.","choices":["Шотландия","Англия","Дания","Канада","США"],"answer":1,"title":"Правила бадминтона","steps":["Игра с воланом была известна в разных странах, в том числе в Индии. Название современной игры связано с английским поместьем Бадминтон-хаус.","Один из первых сводов правил составил Бадминтонский клуб города Бат. Бат и Бадминтон-хаус находятся в Англии."]},{"question":"В каких странах были придуманы современные виды следующих спортивных игр:\n\nКёрлинг.","choices":["Шотландия","Англия","Дания","Канада","США"],"answer":0,"title":"Камни на льду","steps":["Кёрлинг похож на старинную зимнюю игру, в которой тяжёлый камень пускали по льду к цели. Ранние письменные свидетельства найдены в Шотландии.","Там же появились влиятельные клубы, установившие правила современного кёрлинга. Выбираем Шотландию."]},{"question":"В каких странах были придуманы современные виды следующих спортивных игр:\n\nБаскетбол.","choices":["Шотландия","Англия","Дания","Канада","США"],"answer":4,"title":"Первые корзины","steps":["В 1891 году преподаватель Джеймс Нейсмит придумал заловую игру. Первой мишенью стали подвешенные корзины из-под персиков.","Он работал в Спрингфилде, штат Массачусетс. Там, в США, возник баскетбол."]},{"question":"Какие музыкальные инструменты изображены на иллюстрациях?","choices":["Флейта","Фагот","Валторна","Тромбон","Труба"],"answer":1,"title":"Длинный деревянный духовой","figure":{"src":"assets/golden-fleece/2004/2004_26_big.jpg","alt":"Длинный тёмный инструмент с клапанами и маленькой изогнутой трубкой.","width":200,"height":421},"steps":["От корпуса отходит изогнутая тонкая трубка, через которую музыкант дует в двойную трость. Основная часть инструмента довольно длинная.","Двойная трость и изогнутая трубка-эс характерны для фагота."]},{"question":"Какие музыкальные инструменты изображены на иллюстрациях?","choices":["Флейта","Фагот","Валторна","Тромбон","Труба"],"answer":3,"title":"Медный духовой с кулисой","figure":{"src":"assets/golden-fleece/2004/2004_27_big.jpg","alt":"Медный духовой инструмент с длинной подвижной U-образной трубкой.","width":200,"height":346},"steps":["Между мундштуком и раструбом видна длинная выдвижная трубка. Её длину меняют, чтобы получить звуки разной высоты.","Такая трубка называется кулисой. По ней узнаём тромбон."]},{"question":"Какие музыкальные инструменты изображены на иллюстрациях?","choices":["Флейта","Фагот","Валторна","Тромбон","Труба"],"answer":0,"title":"Духовой с клапанами","figure":{"src":"assets/golden-fleece/2004/2004_28_big.jpg","alt":"Тонкая прямая металлическая трубка с клапанами.","width":200,"height":419},"steps":["Видна прямая тонкая трубка с отверстиями и клапанами. У неё нет большого раструба, характерного для медных духовых из этого списка.","У поперечной флейты дуют в отверстие на головке инструмента. Среди вариантов подходит флейта."]},{"question":"Какие музыкальные инструменты изображены на иллюстрациях?","choices":["Флейта","Фагот","Валторна","Тромбон","Труба"],"answer":2,"title":"Свёрнутая трубка","figure":{"src":"assets/golden-fleece/2004/2004_29_big.jpg","alt":"Медный духовой инструмент со свёрнутой в круг трубкой и широким раструбом.","width":304,"height":200},"steps":["Трубка свёрнута широкими кругами. С одного конца у неё мундштук, а с другого — широкий раструб.","Так выглядит валторна. Её форма напоминает форму охотничьего рога, от которого она произошла."]},{"question":"Какие музыкальные инструменты изображены на иллюстрациях?","choices":["Флейта","Фагот","Валторна","Тромбон","Труба"],"answer":4,"title":"Компактный медный духовой","figure":{"src":"assets/golden-fleece/2004/2004_30_big.jpg","alt":"Компактный медный духовой инструмент с тремя клапанами и горизонтальным раструбом.","width":469,"height":294},"steps":["У инструмента горизонтальный раструб и три клапана. Трубка уложена компактно, чтобы музыкант мог удерживать корпус одной рукой.","Это труба. В отличие от длинной кулисы тромбона, здесь звуки меняют нажатием клапанов."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
